from fractions import Fraction


def fraction_expr(s: str) -> str:
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        if s[i].isspace():
            i += 1
            continue

        ch = s[i]

        if ch in "+-*()":
            tokens.append(ch)
            i += 1
            continue

        if "0" <= ch <= "9":
            start = i
            while i < n and "0" <= s[i] <= "9":
                i += 1

            numerator = int(s[start:i])

            if i < n and s[i] == "/":
                i += 1
                denom_start = i
                while i < n and "0" <= s[i] <= "9":
                    i += 1

                if denom_start == i:
                    raise ValueError("Malformed fraction")

                denominator = int(s[denom_start:i])
                if denominator == 0:
                    raise ValueError("Zero denominator")

                tokens.append(("number", Fraction(numerator, denominator)))
            else:
                tokens.append(("number", Fraction(numerator)))
            continue

        raise ValueError("Malformed input")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def parse_primary():
        nonlocal pos

        if pos >= len(tokens):
            raise ValueError("Expected operand")

        token = tokens[pos]

        if token == "(":
            pos += 1
            value = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ")":
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return value

        if isinstance(token, tuple) and token[0] == "number":
            pos += 1
            return token[1]

        raise ValueError("Expected operand")

    def parse_factor():
        nonlocal pos

        if pos < len(tokens) and tokens[pos] == "-":
            pos += 1
            return -parse_primary()

        return parse_primary()

    def parse_term():
        nonlocal pos

        value = parse_factor()
        while pos < len(tokens) and tokens[pos] == "*":
            pos += 1
            value *= parse_factor()
        return value

    def parse_expression():
        nonlocal pos

        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ("+", "-"):
            operator = tokens[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if operator == "+" else value - rhs
        return value

    result = parse_expression()

    if pos != len(tokens):
        raise ValueError("Malformed expression")

    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"
